</template>

<script setup>
import imageGenplan from "@/assets/img/components/houses/genpaln-house.webp"
import {computed, onMounted, onUpdated, onActivated, ref, nextTick, watch} from "vue";
import { vElementHover } from '@vueuse/components'
import { useElementVisibility, useImage } from '@vueuse/core'

/**
 *=========
 * props
 *=========
 */
const props = defineProps({
	housesData: {
		type: Array,
        default: () => []
    }
})

/**
 *=========
 * data
 *=========
 */

const genplanWrapper = ref(null)
const genplan = ref(null)
const activeHouse = ref({})
const numberStatusesforHouses = ref([])
const genplanIsVisivble = useElementVisibility(genplan)
const { isLoading } = useImage({ src: imageGenplan })
const allNumbersOfHouses = Array(29).fill().map((_, idx) => idx+ 1)

/**
 *=========
 * computed
 *=========
 */

const availableHouse = computed(() => {
	const housePresence = {};

	// Инициализируем все номера домов как false (не присутствуют)
	for (let i = 1; i <= allNumbersOfHouses.length; i++) {
		housePresence[i] = false;
	}

	// Устанавливаем true для номеров домов, которые присутствуют в массиве объектов
	props.housesData.forEach(obj => {
		const houseNumber = +obj.number;
		if (houseNumber >= 1 && houseNumber <= allNumbersOfHouses.length) {
			housePresence[houseNumber] = true;
		}
	});

	// Преобразуем объект в массив, сохраняя порядок номеров домов
	const resultArray = allNumbersOfHouses.map(houseNumber => housePresence[houseNumber]);

	return resultArray;
})

/**
 *=========
 * methods
 *=========
 */

function onHoveredMask(state, elNumber) {
	if (!props.housesData.find(house => +house.number === +elNumber)) return
    if (!genplan.value) return
	const houseActiveClass = 'genplan__house-mask--active'
	const doodleActiveClass = 'genplan__doodle--active'
	const mask = genplan.value.querySelector(`[data-house-mask="${elNumber}"]`)
	const house = genplan.value.querySelector(`[data-house="${elNumber}"]`)
	const doodle = document.querySelector(`.genplan__doodle`)
	const genplanWrapper = document.querySelector('.genplan')
	state ?
		mask.classList.add(houseActiveClass) :
		mask.classList.remove(houseActiveClass)
	state ?
		doodle.classList.add(doodleActiveClass) :
		doodle.classList.remove(doodleActiveClass)
	const {width: widthHouse, x, y} = house.getBoundingClientRect()
	const {x: xGenplan, y: yGenplan} = genplanWrapper.getBoundingClientRect()

	setActiveHouseFromNumber(elNumber)
	doodle.style.top = y - yGenplan - doodle.getBoundingClientRect().height + "px"
	doodle.style.left = x - xGenplan + (widthHouse / 2) - (doodle.getBoundingClientRect().width / 2) + "px"
	// console.log('hov', house.getBoundingClientRect())
}

function setActiveHouseFromNumber(numberHouse) {
	activeHouse.value = props.housesData.find(house => Number(house.number) === numberHouse)
}

// редирект на конкретную страницу дома
function goToHome(homeNumber) {
	if (!props.housesData.find(house => +house.number === homeNumber)) return
	window.location = window.location.origin + '/house/?district=' + homeNumber
}

</script>

